const VARS = ['--bg','--surface','--line','--text','--muted','--acc','--on','--soft','--warm','--onwarm'];
function pickTheme(t) {
  t = t.toLowerCase();
  if (/clean|ward|chart/.test(t)) return 'clean';
  if (/mud|olive|khaki/.test(t)) return 'mud';
  if (/bright green|lime|neon|wake/.test(t)) return 'wake';
  if (/sunset|red/.test(t)) return 'sunset';
  if (/sunrise|orange|peach|warm/.test(t)) return 'sunrise';
  if (/blue|ocean|sea|navy/.test(t)) return 'ocean';
  if (/green|forest|nature|calm/.test(t)) return 'forest';
  if (/purple|dusk|lavender|pink/.test(t)) return 'dusk';
  if (/black|white|mono|minimal|plain/.test(t)) return 'mono';
  if (/midnight|dark|monitor/.test(t)) return 'midnight';
  return null;
}
function pickSlot(t) {
  t = t.toLowerCase();
  if (/morning|wake|sunrise|\bam\b/.test(t)) return 'morning';
  if (/evening|night|sunset|\bpm\b/.test(t)) return 'evening';
  return null;
}
function readProfile(t, p) {
  const y = t.match(/\b(final|first|second|third|fourth|fifth|\d(?:st|nd|rd|th)?)\s*year\b|\byear\s*(\d)\b/i);
  const u = t.match(/\b(?:at|from)\s+([A-Z][\w'-]*(?:\s+[A-Z][\w'-]*)*)/);
  const c = /usmle/i.test(t) ? 'USMLE' : /plab/i.test(t) ? 'PLAB' : /ukmla|\bmla\b|\buk\b|manchester|leeds|london|glasgow/i.test(t) ? 'UKMLA' : p.curriculum;
  const clean = y ? (y[1] ? y[1] + ' year' : 'Year ' + y[2]) : p.year;
  return { year: clean.charAt(0).toUpperCase() + clean.slice(1), uni: u ? u[1] : p.uni, curriculum: c };
}
const GLOSSARY = {
  'af': 'Atrial fibrillation: the atria quiver instead of squeezing, so the pulse is irregularly irregular.',
  'atrial fibrillation': 'The atria quiver instead of squeezing, so the pulse is irregularly irregular and clots can form.',
  'appendage': 'A small pouch off the left atrium. Blood sits still there in AF, which is why most clots form there.',
  'cha2ds2-vasc': 'A score for stroke risk in AF. Heart failure, hypertension, age, diabetes, stroke, vascular disease and sex all count.',
  'curb-65': 'A pneumonia severity score: confusion, urea, respiratory rate, blood pressure and age 65 or over.',
  'fio2': 'The fraction of oxygen being breathed. Room air is about 0.21.',
  'pco2': 'How much carbon dioxide is in the blood. High means under-ventilating.',
  'hco3': 'Bicarbonate, the metabolic side of acid-base. It rises over days to compensate for a respiratory acidosis.',
  'lactate': 'A marker of tissue hypoperfusion or anaerobic metabolism.',
  'ischaemic': 'Caused by blocked blood supply rather than bleeding.',
  'peaked t waves': 'Tall, narrow T waves on ECG, an early sign of hyperkalaemia.',
  'ssri': 'Selective serotonin reuptake inhibitor, the usual first antidepressant class.'
};
function explainLocal(text) {
  const t = text.toLowerCase();
  const key = Object.keys(GLOSSARY).filter(k => k.length > 2 ? t.includes(k) : new RegExp('\\b' + k + '\\b').test(t))[0];
  return key ? GLOSSARY[key] : "Claude isn't reachable from this view, so I can't answer that here.";
}
