function loadPrefs() { try { return JSON.parse(localStorage.getItem('medos.links.v1')) || { pins: { BNF: true }, opens: {} }; } catch (e) { return { pins: { BNF: true }, opens: {} }; } }
function loadLibrary() { try { const saved = JSON.parse(localStorage.getItem('medos.library.v1')); if (saved) return saved.filter(x => x.items.length).map(x => x.name === 'Acronyms and teaching points' ? { ...x, name: 'Mnemonics and teaching points' } : x); } catch (e) {} return null; }
function sortMemory(text, typed) {
  const t = text.toLowerCase();
  if (/acronym|mnemonic|teaching point|remember that|rule of|\b[a-z]\s*=\s*/.test(t)) return 'Mnemonics and teaching points';
  if (/slide|lecture|\.pptx?$|tutorial/.test(t)) return 'Lecture slides';
  if (/osce|station|cca|cpsa|ospe/.test(t)) return 'OSCEs from older years';
  if (/past|paper|mock|question|akt|\bsba\b|exam/.test(t)) return 'Past questions';
  if (/anki|\.apkg|\.colpkg/.test(t)) return 'Anki';
  return typed ? 'What it remembers' : 'Other files';
}
