const CONSULTANT_BASE = ' You are teaching a UK final-year medical student. Reply in under 80 words. Ask one question at a time. Use UK terms. This is for education, not real patient care; if you are unsure, say so.';
function ecgPts(normal, x0, x1, base, amp) {
  const pts = []; let x = x0;
  if (normal) {
    while (x + 50 < x1) { [[0,0],[6,-.13],[11,0],[15,0],[18,.08],[21,-1],[25,.26],[28,0],[36,-.24],[44,0],[52,0]].forEach(([dx, dy]) => pts.push((x + dx) + ',' + (base + dy * amp))); x += 52; }
  } else {
    const gaps = [34,68,28,52,80,38,60,30]; let i = 0;
    while (x < x1) { const g = gaps[i++ % gaps.length]; for (let k = 0; k < g - 8 && x + k < x1; k += 4) pts.push((x + k) + ',' + (base + ((k * 7 + i * 5) % 7) - 3)); const qx = x + g - 8; if (qx + 7 < x1) [[0,.08],[3,-1],[6,.26],[8,0]].forEach(([dx, dy]) => pts.push((qx + dx) + ',' + (base + dy * amp))); x += g; }
  }
  return pts.join(' ');
}

