function calcResult(c, st) { st = st || {}; if (c.fields) { const v = { sex: st.sex || 'M' }; for (const [k] of c.fields) { const n = parseFloat(st[k]); if (isNaN(n) || (n === 0 && /str|hrs|cr|hr|ht/.test(k))) return null; v[k] = n; } return { text: c.calc(v), note: c.note ? c.note(v) : '' }; } let t = 0; (c.selects || []).forEach(([, o], i) => { const p = st['s' + i]; t += p === undefined ? (o.find(x => x[1] === 0) || o[0])[1] : o[p][1]; }); (c.items || []).forEach(([, pts], i) => { if (st['i' + i]) t += pts; }); return { text: String(t), note: band(t, c.bands), extra: c.note ? c.note() : '' }; }
